package com.gameaggregator.tenantservice.domain; import com.gameaggregator.platform.core.common.persistence.BaseEntity; import jakarta.persistence.*; import java.util.UUID; @Entity @Table(name="organizations",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","slug"})) public class Organization extends BaseEntity { @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(nullable=false,length=120) private String slug; @Column(nullable=false,length=200) private String name; @Column(nullable=false,length=30) private String type; protected Organization(){} public Organization(UUID tenantId,String slug,String name,String type){this.tenantId=tenantId;this.slug=slug;this.name=name;this.type=type;} public UUID getTenantId(){return tenantId;} public String getSlug(){return slug;} public String getName(){return name;} public String getType(){return type;} }
